insert into public.countries (iso2, region, wiki, capital_uk, capital_pl, capital_en, intro_uk, intro_pl, intro_en, best_months, daily_cost, tags, airport_code, airport_name, airport_lat, airport_lng) values
  ('AD', 'west', 'Andorra', 'Андорра-ла-Велья', 'Andora', 'Andorra la Vella', 'Гірська країна в Піренеях з лижними курортами, шопінгом без мит і термальними спа. Взимку — сноуборд, улітку — хайкінг.', 'Górskie państwo w Pirenejach z ośrodkami narciarskimi, zakupami bez cła i termami. Zimą snowboard, latem trekking.', 'A Pyrenean country of ski resorts, duty-free shopping and thermal spas. Snowboarding in winter, hiking in summer.', array[1, 2, 3, 7, 8, 12]::smallint[], 65, array['mountains', 'nature', 'family', 'comfort']::text[], 'BCN', 'Barcelona El Prat (+ автобус 3 год)', 41.3, 2.08),
  ('AL', 'balkans', 'Albania', 'Тирана', 'Tirana', 'Tirana', 'Бірюзове Іонічне море, османські містечка на схилах гір і одні з найдоступніших цін у Європі. Албанія — секрет, який швидко перестає бути секретом.', 'Turkusowe Morze Jońskie, osmańskie miasteczka na zboczach gór i jedne z najniższych cen w Europie. Albania to sekret, który szybko przestaje być sekretem.', 'Turquoise Ionian Sea, Ottoman towns on mountain slopes and some of the lowest prices in Europe. Albania is a secret that is quickly ceasing to be one.', array[5, 6, 7, 8, 9]::smallint[], 30, array['sea', 'history', 'nature', 'food', 'mountains']::text[], 'TIA', 'Tirana Nënë Tereza', 41.41, 19.72),
  ('AT', 'west', 'Austria', 'Відень', 'Wiedeń', 'Vienna', 'Імперський Відень, Моцартів Зальцбург, альпійські озера влітку й гірськолижні курорти взимку. Австрія — це елегантність і свіже гірське повітря.', 'Cesarski Wiedeń, Salzburg Mozarta, alpejskie jeziora latem i stoki narciarskie zimą. Austria to elegancja i świeże górskie powietrze.', 'Imperial Vienna, Mozart’s Salzburg, alpine lakes in summer and ski resorts in winter. Austria is elegance and fresh mountain air.', array[5, 6, 7, 8, 9, 12, 1, 2]::smallint[], 80, array['mountains', 'history', 'city', 'nature', 'comfort']::text[], 'VIE', 'Vienna International', 48.11, 16.57),
  ('BA', 'balkans', 'Bosnia and Herzegovina', 'Сараєво', 'Sarajewo', 'Sarajevo', 'Старий міст у Мостарі, кав''ярні Сараєва, де Схід зустрічається із Заходом, і смарагдові водоспади. Боснія й Герцеговина дивує на кожному кроці.', 'Stary Most w Mostarze, kawiarnie Sarajewa, gdzie Wschód spotyka Zachód, i szmaragdowe wodospady. Bośnia i Hercegowina zaskakuje na każdym kroku.', 'The Old Bridge in Mostar, Sarajevo’s cafés where East meets West, and emerald waterfalls. Bosnia and Herzegovina surprises at every turn.', array[5, 6, 7, 8, 9]::smallint[], 30, array['history', 'nature', 'food', 'mountains']::text[], 'SJJ', 'Sarajevo International', 43.82, 18.33),
  ('BE', 'west', 'Belgium', 'Брюссель', 'Bruksela', 'Brussels', 'Шоколад, вафлі, сотні сортів пива й середньовічні міста, наче з листівки. Бельгія маленька, але кожне місто тут — окрема пригода.', 'Czekolada, gofry, setki gatunków piwa i średniowieczne miasta jak z pocztówki. Belgia jest mała, ale każde miasto to osobna przygoda.', 'Chocolate, waffles, hundreds of beers and medieval towns straight off a postcard. Belgium is small, but every city is an adventure of its own.', array[4, 5, 6, 7, 8, 9, 12]::smallint[], 80, array['city', 'history', 'food', 'couples']::text[], 'BRU', 'Brussels Airport', 50.9, 4.48),
  ('BG', 'east', 'Bulgaria', 'Софія', 'Sofia', 'Sofia', 'Пляжі Чорного моря, гірськолижний Банско, Рильський монастир і одні з найнижчих цін у ЄС. Болгарія чудово підходить для сімейного відпочинку.', 'Plaże Morza Czarnego, narciarskie Bansko, Monastyr Rylski i jedne z najniższych cen w UE. Bułgaria świetnie nadaje się na rodzinny wypoczynek.', 'Black Sea beaches, ski resort Bansko, the Rila Monastery and some of the lowest prices in the EU. Bulgaria is great for family holidays.', array[1, 2, 6, 7, 8, 9]::smallint[], 35, array['sea', 'mountains', 'history', 'family', 'food']::text[], 'SOF', 'Sofia Airport', 42.7, 23.41),
  ('CH', 'west', 'Switzerland', 'Берн', 'Berno', 'Bern', 'Сніжні вершини, кришталеві озера, панорамні потяги й найсмачніший шоколад. Швейцарія дорога, але кожен франк тут вартий краєвидів.', 'Ośnieżone szczyty, krystaliczne jeziora, panoramiczne pociągi i najlepsza czekolada. Szwajcaria jest droga, ale każdy frank jest wart tych widoków.', 'Snowy peaks, crystal lakes, panoramic trains and the best chocolate. Switzerland is expensive, but every franc is worth the views.', array[1, 2, 3, 6, 7, 8, 9, 12]::smallint[], 130, array['mountains', 'nature', 'comfort', 'couples', 'city']::text[], 'ZRH', 'Zürich Airport', 47.46, 8.55),
  ('CY', 'south', 'Cyprus', 'Нікосія', 'Nikozja', 'Nicosia', 'Острів Афродіти з 340 сонячними днями на рік, блакитними лагунами й античними руїнами. Кіпр — ідеальне море з квітня по листопад.', 'Wyspa Afrodyty z 340 słonecznymi dniami w roku, błękitnymi lagunami i antycznymi ruinami. Cypr to idealne morze od kwietnia do listopada.', 'Aphrodite’s island with 340 sunny days a year, blue lagoons and ancient ruins. Cyprus offers perfect sea from April to November.', array[4, 5, 6, 7, 8, 9, 10, 11]::smallint[], 60, array['sea', 'history', 'nightlife', 'family', 'comfort']::text[], 'LCA', 'Larnaca International', 34.88, 33.63),
  ('CZ', 'central', 'Czech Republic', 'Прага', 'Praga', 'Prague', 'Готичні шпилі Праги, чеське пиво за копійки й замки на кожному пагорбі. Чехія — одна з найкрасивіших і найдоступніших країн Європи.', 'Gotyckie iglice Pragi, tanie czeskie piwo i zamki na każdym wzgórzu. Czechy to jeden z najpiękniejszych i najtańszych krajów Europy.', 'Prague’s Gothic spires, cheap Czech beer and a castle on every hill. Czechia is one of Europe’s most beautiful and affordable countries.', array[4, 5, 6, 7, 8, 9, 12]::smallint[], 50, array['city', 'history', 'food', 'nightlife', 'couples']::text[], 'PRG', 'Praha Václav Havel', 50.1, 14.26),
  ('DE', 'west', 'Germany', 'Берлін', 'Berlin', 'Berlin', 'Казкові замки, різдвяні ярмарки, пивні сади й найкращі музеї Європи. Німеччина однаково добре підходить для міських вихідних і подорожі Альпами.', 'Bajkowe zamki, jarmarki bożonarodzeniowe, ogródki piwne i jedne z najlepszych muzeów Europy. Niemcy sprawdzą się zarówno na miejski weekend, jak i na wyprawę w Alpy.', 'Fairy-tale castles, Christmas markets, beer gardens and some of Europe’s best museums. Germany works equally well for a city weekend or an Alpine trip.', array[5, 6, 7, 8, 9, 12]::smallint[], 75, array['city', 'history', 'food', 'nightlife', 'mountains', 'family']::text[], 'BER', 'Berlin Brandenburg', 52.36, 13.5),
  ('DK', 'north', 'Denmark', 'Копенгаген', 'Kopenhaga', 'Copenhagen', 'Кольорова набережна Нюгавн, «хюґе», велосипеди й батьківщина LEGO. Данія — затишна країна дизайну та казок Андерсена.', 'Kolorowe nabrzeże Nyhavn, „hygge”, rowery i ojczyzna LEGO. Dania to przytulny kraj designu i baśni Andersena.', 'Colourful Nyhavn, “hygge”, bicycles and the home of LEGO. Denmark is a cosy land of design and Andersen’s fairy tales.', array[5, 6, 7, 8, 12]::smallint[], 100, array['city', 'family', 'food', 'sea', 'couples']::text[], 'CPH', 'Copenhagen Kastrup', 55.62, 12.65),
  ('EE', 'north', 'Estonia', 'Таллінн', 'Tallinn', 'Tallinn', 'Середньовічний Таллінн, болота й ліси, острови Балтики та цифрова держава майбутнього. Естонія — компактна й дуже зручна для подорожі.', 'Średniowieczny Tallinn, bagna i lasy, bałtyckie wyspy i cyfrowe państwo przyszłości. Estonia jest kompaktowa i bardzo wygodna w podróży.', 'Medieval Tallinn, bogs and forests, Baltic islands and a digital state of the future. Estonia is compact and very easy to travel.', array[5, 6, 7, 8, 12]::smallint[], 55, array['history', 'city', 'nature', 'sea']::text[], 'TLL', 'Tallinn Lennart Meri', 59.41, 24.83),
  ('ES', 'south', 'Spain', 'Мадрид', 'Madryt', 'Madrid', 'Сонце понад 300 днів на рік, фламенко, тапас до пізньої ночі та архітектура Гауді. Іспанія вміє жити повільно і смачно.', 'Ponad 300 słonecznych dni w roku, flamenco, tapas do późnej nocy i architektura Gaudíego. Hiszpania umie żyć powoli i smacznie.', 'Sunshine 300+ days a year, flamenco, tapas until late at night and Gaudí’s architecture. Spain knows how to live slowly and deliciously.', array[4, 5, 6, 9, 10]::smallint[], 65, array['sea', 'city', 'food', 'nightlife', 'history']::text[], 'BCN', 'Barcelona-El Prat', 41.3, 2.08),
  ('FI', 'north', 'Finland', 'Гельсінкі', 'Helsinki', 'Helsinki', 'Тисячі озер, сауни, Лапландія з Санта-Клаусом і білі ночі. Фінляндія — найкраще місце для зимової казки.', 'Tysiące jezior, sauny, Laponia ze Świętym Mikołajem i białe noce. Finlandia to najlepsze miejsce na zimową bajkę.', 'Thousands of lakes, saunas, Lapland with Santa Claus and white nights. Finland is the best place for a winter fairy tale.', array[1, 2, 3, 6, 7, 8, 12]::smallint[], 90, array['nature', 'family', 'couples', 'comfort', 'city']::text[], 'HEL', 'Helsinki-Vantaa', 60.32, 24.96),
  ('FR', 'west', 'France', 'Париж', 'Paryż', 'Paris', 'Париж, Лазурний берег, лавандові поля Провансу й тисяча сортів сиру. Франція — найвідвідуваніша країна світу, і на те є причини.', 'Paryż, Lazurowe Wybrzeże, lawendowe pola Prowansji i tysiąc gatunków sera. Francja to najczęściej odwiedzany kraj świata — i nie bez powodu.', 'Paris, the Riviera, Provence’s lavender fields and a thousand kinds of cheese. France is the most visited country in the world — for good reason.', array[4, 5, 6, 9]::smallint[], 85, array['city', 'food', 'history', 'sea', 'couples', 'mountains']::text[], 'CDG', 'Paris Charles de Gaulle', 49.01, 2.55),
  ('GB', 'west', 'United Kingdom', 'Лондон', 'Londyn', 'London', 'Королівські палаци, шотландські замки, пабові традиції та безкоштовні музеї світового рівня. Велика Британія — це чотири країни в одній подорожі.', 'Królewskie pałace, szkockie zamki, tradycje pubowe i darmowe muzea światowej klasy. Wielka Brytania to cztery kraje w jednej podróży.', 'Royal palaces, Scottish castles, pub traditions and free world-class museums. The United Kingdom is four countries in one trip.', array[5, 6, 7, 8, 9]::smallint[], 95, array['city', 'history', 'nature', 'nightlife', 'mountains']::text[], 'LHR', 'London Heathrow', 51.47, -0.45),
  ('GR', 'south', 'Greece', 'Афіни', 'Ateny', 'Athens', 'Тисячі островів, білі будиночки з синіми дверима, античні храми та свіжа риба на березі. Греція — класика літнього відпочинку.', 'Tysiące wysp, białe domki z niebieskimi drzwiami, antyczne świątynie i świeża ryba nad brzegiem. Grecja to klasyka letnich wakacji.', 'Thousands of islands, white houses with blue doors, ancient temples and fresh fish by the shore. Greece is the classic summer escape.', array[5, 6, 7, 8, 9, 10]::smallint[], 60, array['sea', 'history', 'food', 'couples', 'nature']::text[], 'ATH', 'Athens Eleftherios Venizelos', 37.94, 23.94),
  ('HR', 'balkans', 'Croatia', 'Загреб', 'Zagrzeb', 'Zagreb', 'Понад тисяча островів, кришталева Адріатика, римські палаци та бірюзові озера Плітвіце. Хорватія — ідеальне поєднання моря та історії.', 'Ponad tysiąc wysp, krystaliczny Adriatyk, rzymskie pałace i turkusowe Jeziora Plitwickie. Chorwacja to idealne połączenie morza i historii.', 'Over a thousand islands, the crystal Adriatic, Roman palaces and the turquoise Plitvice Lakes. Croatia is the perfect mix of sea and history.', array[5, 6, 7, 8, 9]::smallint[], 60, array['sea', 'history', 'nature', 'couples']::text[], 'SPU', 'Split Airport', 43.54, 16.3),
  ('HU', 'central', 'Hungary', 'Будапешт', 'Budapeszt', 'Budapest', 'Термальні купальні, руїн-бари, гуляш і найкрасивіший парламент Європи. Угорщина — це не лише Будапешт, а й озеро Балатон та винні долини.', 'Łaźnie termalne, ruin bary, gulasz i najpiękniejszy parlament Europy. Węgry to nie tylko Budapeszt, ale i Balaton oraz winne doliny.', 'Thermal baths, ruin bars, goulash and Europe’s most beautiful parliament. Hungary is more than Budapest — there’s Lake Balaton and wine valleys too.', array[4, 5, 6, 7, 8, 9]::smallint[], 50, array['city', 'nightlife', 'food', 'history', 'comfort']::text[], 'BUD', 'Budapest Ferenc Liszt', 47.44, 19.26),
  ('IE', 'west', 'Republic of Ireland', 'Дублін', 'Dublin', 'Dublin', 'Зелені пагорби, скелі Мохер, живий фольк у пабах і замки біля океану. Ірландія — країна легенд, дощу й тепла людей.', 'Zielone wzgórza, klify Moher, muzyka folk na żywo w pubach i zamki nad oceanem. Irlandia to kraj legend, deszczu i ciepła ludzi.', 'Green hills, the Cliffs of Moher, live folk music in pubs and castles by the ocean. Ireland is a land of legends, rain and warm people.', array[5, 6, 7, 8, 9]::smallint[], 90, array['nature', 'city', 'nightlife', 'history']::text[], 'DUB', 'Dublin Airport', 53.43, -6.27),
  ('IS', 'north', 'Iceland', 'Рейк''явік', 'Reykjavik', 'Reykjavík', 'Вулкани, гейзери, льодовики, водоспади й північне сяйво — Ісландія схожа на іншу планету. Найкраще її досліджувати на машині.', 'Wulkany, gejzery, lodowce, wodospady i zorza polarna — Islandia przypomina inną planetę. Najlepiej zwiedzać ją samochodem.', 'Volcanoes, geysers, glaciers, waterfalls and the northern lights — Iceland feels like another planet. It’s best explored by car.', array[1, 2, 3, 6, 7, 8, 9]::smallint[], 120, array['nature', 'mountains', 'couples', 'comfort']::text[], 'KEF', 'Keflavík International', 63.99, -22.62),
  ('IT', 'south', 'Italy', 'Рим', 'Rzym', 'Rome', 'Римські руїни, ренесансні шедеври, кольорові селища над морем і паста, яку в кожному регіоні готують по-своєму. Італія — це країна, куди повертаються.', 'Rzymskie ruiny, renesansowe arcydzieła, kolorowe miasteczka nad morzem i makaron, który w każdym regionie robi się inaczej. Do Włoch się wraca.', 'Roman ruins, Renaissance masterpieces, colourful villages above the sea and pasta that every region makes its own way. Italy is the country people keep coming back to.', array[4, 5, 6, 9, 10]::smallint[], 75, array['history', 'food', 'sea', 'city', 'couples']::text[], 'FCO', 'Roma Fiumicino', 41.8, 12.25),
  ('LI', 'west', 'Liechtenstein', 'Вадуц', 'Vaduz', 'Vaduz', 'Крихітне князівство між Швейцарією та Австрією з княжим замком, виноградниками та альпійськими стежками. Країну можна пройти пішки за день.', 'Maleńkie księstwo między Szwajcarią a Austrią z zamkiem książęcym, winnicami i alpejskimi szlakami. Kraj można przejść pieszo w jeden dzień.', 'A tiny principality between Switzerland and Austria with a prince’s castle, vineyards and Alpine trails. You can walk across the whole country in a day.', array[1, 2, 6, 7, 8, 9]::smallint[], 120, array['mountains', 'nature', 'comfort', 'couples']::text[], 'ZRH', 'Zürich Airport (+ потяг 1,5 год)', 47.46, 8.55),
  ('LT', 'north', 'Lithuania', 'Вільнюс', 'Wilno', 'Vilnius', 'Барокове старе місто Вільнюса, замок на озері в Тракаї та дюни Куршської коси. Литва — тепла, зелена й дуже близька до Польщі.', 'Barokowe stare miasto Wilna, zamek na jeziorze w Trokach i wydmy Mierzei Kurońskiej. Litwa jest ciepła, zielona i bardzo bliska Polsce.', 'Vilnius’s Baroque old town, Trakai’s island castle and the dunes of the Curonian Spit. Lithuania is warm, green and very close to Poland.', array[5, 6, 7, 8, 9, 12]::smallint[], 45, array['history', 'city', 'sea', 'nature', 'food']::text[], 'VNO', 'Vilnius International', 54.63, 25.29),
  ('LU', 'west', 'Luxembourg', 'Люксембург', 'Luksemburg', 'Luxembourg', 'Фортеця на скелях, казкові долини й безкоштовний громадський транспорт по всій країні. Люксембург — ідеальний для коротких вихідних.', 'Twierdza na skałach, bajkowe doliny i darmowa komunikacja publiczna w całym kraju. Luksemburg jest idealny na krótki weekend.', 'A fortress on the rocks, fairy-tale valleys and free public transport nationwide. Luxembourg is perfect for a short weekend.', array[5, 6, 7, 8, 9]::smallint[], 90, array['history', 'nature', 'city', 'couples', 'comfort']::text[], 'LUX', 'Luxembourg Findel', 49.63, 6.21),
  ('LV', 'north', 'Latvia', 'Рига', 'Ryga', 'Riga', 'Ар-нуво Риги, дюни Юрмали, середньовічні замки й соснові ліси. Латвія поєднує столичний шарм і тихий балтійський відпочинок.', 'Secesja Rygi, wydmy Jurmały, średniowieczne zamki i sosnowe lasy. Łotwa łączy stołeczny urok z cichym bałtyckim wypoczynkiem.', 'Riga’s Art Nouveau, the dunes of Jūrmala, medieval castles and pine forests. Latvia combines big-city charm with quiet Baltic holidays.', array[5, 6, 7, 8, 12]::smallint[], 50, array['city', 'history', 'sea', 'nature', 'nightlife']::text[], 'RIX', 'Riga International', 56.92, 23.97),
  ('MD', 'east', 'Moldova', 'Кишинів', 'Kiszyniów', 'Chișinău', 'Країна вина з найбільшими винними підвалами світу, печерними монастирями й гостинністю. Молдова — несподіване відкриття для гурманів.', 'Kraj wina z największymi piwnicami na świecie, skalnymi monastyrami i gościnnością. Mołdawia to zaskakujące odkrycie dla smakoszy.', 'A wine country with the world’s largest wine cellars, cave monasteries and warm hospitality. Moldova is a surprising find for food lovers.', array[5, 6, 9, 10]::smallint[], 30, array['food', 'history', 'nature', 'couples']::text[], 'RMO', 'Chișinău International', 46.93, 28.93),
  ('ME', 'balkans', 'Montenegro', 'Подгориця', 'Podgorica', 'Podgorica', 'Маленька країна з великими горами: фіорд Котора, гірські озера Дурмітора й пляжі Будви за кілька годин один від одного.', 'Mały kraj z wielkimi górami: fiord Kotoru, górskie jeziora Durmitoru i plaże Budvy w odległości kilku godzin.', 'A small country with big mountains: the Bay of Kotor, the glacial lakes of Durmitor and the beaches of Budva, just hours apart.', array[5, 6, 7, 8, 9]::smallint[], 45, array['sea', 'mountains', 'nature', 'history']::text[], 'TIV', 'Tivat Airport', 42.4, 18.72),
  ('MK', 'balkans', 'North Macedonia', 'Скоп''є', 'Skopje', 'Skopje', 'Охридське озеро — одне з найстаріших у світі, древні церкви, гори й найдоступніші ціни на Балканах. Північна Македонія — тиха перлина регіону.', 'Jezioro Ochrydzkie, jedno z najstarszych na świecie, dawne cerkwie, góry i najniższe ceny na Bałkanach. Macedonia Północna to cicha perła regionu.', 'Lake Ohrid — one of the oldest in the world — ancient churches, mountains and the lowest prices in the Balkans. North Macedonia is the region’s quiet gem.', array[5, 6, 7, 8, 9]::smallint[], 28, array['nature', 'history', 'sea', 'food', 'family']::text[], 'SKP', 'Skopje International', 41.96, 21.62),
  ('MT', 'south', 'Malta', 'Валетта', 'Valletta', 'Valletta', 'Лицарські фортеці, Блакитна лагуна й кіно-локації «Гри престолів». Мальта — маленький острів з 7000 років історії.', 'Twierdze rycerskie, Błękitna Laguna i plenery „Gry o tron”. Malta to mała wyspa z 7000 lat historii.', 'Knights’ fortresses, the Blue Lagoon and “Game of Thrones” locations. Malta is a small island with 7,000 years of history.', array[4, 5, 6, 7, 8, 9, 10]::smallint[], 60, array['sea', 'history', 'nightlife', 'couples']::text[], 'MLA', 'Malta International', 35.86, 14.48),
  ('NL', 'west', 'Netherlands', 'Амстердам', 'Amsterdam', 'Amsterdam', 'Канали, велосипеди, тюльпанові поля й музеї Ван Гога та Рембрандта. Нідерланди легко об''їхати за тиждень потягом.', 'Kanały, rowery, pola tulipanów i muzea Van Gogha oraz Rembrandta. Holandię łatwo objechać pociągiem w tydzień.', 'Canals, bicycles, tulip fields and the museums of Van Gogh and Rembrandt. The Netherlands is easy to explore by train in a week.', array[4, 5, 6, 7, 8, 9]::smallint[], 85, array['city', 'history', 'nightlife', 'nature', 'couples']::text[], 'AMS', 'Amsterdam Schiphol', 52.31, 4.76),
  ('NO', 'north', 'Norway', 'Осло', 'Oslo', 'Oslo', 'Фіорди, водоспади, північне сяйво взимку й сонце опівночі влітку. Норвегія — для тих, хто шукає природу у найвищому її прояві.', 'Fiordy, wodospady, zorza polarna zimą i słońce o północy latem. Norwegia jest dla tych, którzy szukają natury w najlepszym wydaniu.', 'Fjords, waterfalls, northern lights in winter and the midnight sun in summer. Norway is for those who want nature at its most dramatic.', array[6, 7, 8, 12, 1, 2]::smallint[], 110, array['nature', 'mountains', 'sea', 'comfort']::text[], 'OSL', 'Oslo Gardermoen', 60.19, 11.1),
  ('PL', 'central', 'Poland', 'Варшава', 'Warszawa', 'Warsaw', 'Від середньовічного Кракова до балтійських дюн і Татр — Польща поєднує історію, природу та сучасні міста з чудовою їжею за розумні гроші.', 'Od średniowiecznego Krakowa po bałtyckie wydmy i Tatry — Polska łączy historię, przyrodę i nowoczesne miasta z świetnym jedzeniem w rozsądnych cenach.', 'From medieval Kraków to Baltic dunes and the Tatras, Poland combines history, nature and modern cities with great food at fair prices.', array[5, 6, 7, 8, 9]::smallint[], 45, array['history', 'city', 'food', 'mountains', 'sea']::text[], 'KRK', 'Kraków-Balice', 50.08, 19.78),
  ('PT', 'south', 'Portugal', 'Лісабон', 'Lizbona', 'Lisbon', 'Жовті трамваї Лісабона, портвейн у Порту, скелі Алгарве та океанські хвилі для серферів. Португалія — тепла, спокійна й неймовірно фотогенічна.', 'Żółte tramwaje Lizbony, porto w Porto, klify Algarve i oceaniczne fale dla surferów. Portugalia jest ciepła, spokojna i niesamowicie fotogeniczna.', 'Lisbon’s yellow trams, port wine in Porto, the cliffs of the Algarve and ocean waves for surfers. Portugal is warm, calm and endlessly photogenic.', array[4, 5, 6, 9, 10]::smallint[], 60, array['sea', 'city', 'food', 'history', 'nature']::text[], 'LIS', 'Lisbon Humberto Delgado', 38.77, -9.13),
  ('RO', 'east', 'Romania', 'Бухарест', 'Bukareszt', 'Bucharest', 'Замки Трансильванії, мальовничі монастирі, дельта Дунаю й Карпати. Румунія — країна легенд і неймовірної природи за доступними цінами.', 'Zamki Transylwanii, malowane monastyry, delta Dunaju i Karpaty. Rumunia to kraj legend i niesamowitej przyrody w przystępnych cenach.', 'Transylvanian castles, painted monasteries, the Danube Delta and the Carpathians. Romania is a land of legends and stunning nature at fair prices.', array[5, 6, 7, 8, 9, 10]::smallint[], 40, array['history', 'mountains', 'nature', 'food', 'family']::text[], 'OTP', 'Bucharest Henri Coandă', 44.57, 26.08),
  ('RS', 'balkans', 'Serbia', 'Белград', 'Belgrad', 'Belgrade', 'Нічне життя Белграда, фортеці на Дунаї, монастирі та щедра балканська кухня. Сербія вражає гостинністю й енергією.', 'Nocne życie Belgradu, twierdze nad Dunajem, monastery i obfita bałkańska kuchnia. Serbia zachwyca gościnnością i energią.', 'Belgrade nightlife, fortresses on the Danube, monasteries and generous Balkan food. Serbia impresses with hospitality and energy.', array[4, 5, 6, 7, 8, 9]::smallint[], 35, array['city', 'nightlife', 'food', 'history', 'mountains']::text[], 'BEG', 'Belgrade Nikola Tesla', 44.82, 20.31),
  ('SE', 'north', 'Sweden', 'Стокгольм', 'Sztokholm', 'Stockholm', 'Стокгольм на 14 островах, червоні дерев''яні будиночки, Лапландія з північним сяйвом. Швеція — це природа, дизайн і фіка.', 'Sztokholm na 14 wyspach, czerwone drewniane domki, Laponia z zorzą polarną. Szwecja to przyroda, design i fika.', 'Stockholm on 14 islands, red wooden cottages and Lapland under the northern lights. Sweden is nature, design and fika.', array[1, 2, 3, 6, 7, 8, 12]::smallint[], 95, array['nature', 'city', 'sea', 'couples', 'family']::text[], 'ARN', 'Stockholm Arlanda', 59.65, 17.92),
  ('SI', 'central', 'Slovenia', 'Любляна', 'Lublana', 'Ljubljana', 'Озеро Блед з островом-церквою, смарагдова річка Соча, печери й Адріатика — і все це за дві години їзди. Словенія — маленька зелена казка.', 'Jezioro Bled z wyspą-kościołem, szmaragdowa Soča, jaskinie i Adriatyk — wszystko w dwie godziny jazdy. Słowenia to mała zielona bajka.', 'Lake Bled with its island church, the emerald Soča, caves and the Adriatic — all within two hours. Slovenia is a small green fairy tale.', array[5, 6, 7, 8, 9]::smallint[], 60, array['nature', 'mountains', 'sea', 'couples', 'city']::text[], 'LJU', 'Ljubljana Jože Pučnik', 46.22, 14.46),
  ('SK', 'central', 'Slovakia', 'Братислава', 'Bratysława', 'Bratislava', 'Високі Татри, печери, термальні купальні та компактна Братислава на Дунаї. Словаччина — недооцінена перлина для активного відпочинку.', 'Tatry Wysokie, jaskinie, kąpieliska termalne i kameralna Bratysława nad Dunajem. Słowacja to niedoceniana perła aktywnego wypoczynku.', 'The High Tatras, caves, thermal baths and compact Bratislava on the Danube. Slovakia is an underrated gem for active holidays.', array[1, 2, 6, 7, 8, 9, 12]::smallint[], 45, array['mountains', 'nature', 'history', 'family']::text[], 'BTS', 'Bratislava M. R. Štefánik', 48.17, 17.21),
  ('UA', 'east', 'Ukraine', 'Київ', 'Kijów', 'Kyiv', 'Країна золотоверхих соборів, Карпатських полонин і чорноморського узбережжя. Україна дивує поєднанням тисячолітньої історії, гостинності та кухні, яку хочеться пробувати знову й знову.', 'Kraj złotych kopuł, karpackich połonin i czarnomorskiego wybrzeża. Ukraina zaskakuje połączeniem tysiącletniej historii, gościnności i kuchni, do której chce się wracać.', 'A land of golden-domed cathedrals, Carpathian meadows and the Black Sea coast. Ukraine surprises with a thousand years of history, warm hospitality and food you want to try again and again.', array[5, 6, 7, 8, 9]::smallint[], 35, array['history', 'food', 'city', 'mountains']::text[], 'RZE', 'Rzeszów-Jasionka (Польща) + поїзд', 50.11, 22.02),
  ('XK', 'balkans', 'Kosovo', 'Приштина', 'Prisztina', 'Pristina', 'Наймолодша країна Європи з енергійною столицею, османською Прізреном і горами Ругова. Тут дуже дешево й дуже гостинно.', 'Najmłodszy kraj Europy z energiczną stolicą, osmańskim Prizrenem i górami Rugova. Jest tu bardzo tanio i bardzo gościnnie.', 'Europe’s youngest country, with an energetic capital, Ottoman Prizren and the Rugova mountains. It is very affordable and very welcoming.', array[5, 6, 7, 8, 9]::smallint[], 25, array['history', 'mountains', 'nature', 'food']::text[], 'PRN', 'Pristina Adem Jashari', 42.57, 21.04)
insert into public.cities (id, country_iso2, name_uk, name_pl, name_en, wiki, lat, lng, blurb_uk, blurb_pl, blurb_en) values
  ('ad-andorra', 'AD', 'Андорра-ла-Велья', 'Andora', 'Andorra la Vella', 'Andorra la Vella', 42.51, 1.52, 'Найвища столиця Європи та вулиці шопінгу.', 'Najwyżej położona stolica Europy i ulice zakupowe.', 'Europe’s highest capital and its shopping streets.'),
  ('ad-soldeu', 'AD', 'Сольдеу', 'Soldeu', 'Soldeu', 'Soldeu', 42.58, 1.67, 'Центр гірськолижного курорту Грандваліра.', 'Centrum ośrodka narciarskiego Grandvalira.', 'The heart of the Grandvalira ski area.'),
  ('ad-ordino', 'AD', 'Ордіно', 'Ordino', 'Ordino', 'Ordino', 42.56, 1.53, 'Кам''яне село та стежки до озер Тристайна.', 'Kamienna wioska i szlaki do jezior Tristaina.', 'A stone village and trails to the Tristaina lakes.'),
  ('al-tirana', 'AL', 'Тирана', 'Tirana', 'Tirana', 'Tirana', 41.33, 19.82, 'Кольорові будинки, бункер-музей і жвавий район Блоку.', 'Kolorowe kamienice, bunkier-muzeum i tętniąca dzielnica Blloku.', 'Colourful façades, a bunker museum and the lively Blloku district.'),
  ('al-ksamil', 'AL', 'Ксаміль', 'Ksamil', 'Ksamil', 'Ksamil', 39.77, 20, 'Острівці з білим піском і вода кольору Мальдів.', 'Wysepki z białym piaskiem i woda w kolorze Malediwów.', 'White-sand islets and water the colour of the Maldives.'),
  ('al-berat', 'AL', 'Берат', 'Berat', 'Berat', 'Berat', 40.7, 19.95, '«Місто тисячі вікон» під охороною ЮНЕСКО.', '„Miasto tysiąca okien” wpisane na listę UNESCO.', 'The UNESCO-listed “City of a Thousand Windows”.'),
  ('al-sarande', 'AL', 'Саранда', 'Saranda', 'Sarandë', 'Sarandë', 39.87, 20, 'Курортна набережна та пороми на Корфу.', 'Kurortowa promenada i promy na Korfu.', 'A resort promenade and ferries to Corfu.'),
  ('at-vienna', 'AT', 'Відень', 'Wiedeń', 'Vienna', 'Vienna', 48.21, 16.37, 'Палац Шенбрунн, опера та віденські кав''ярні.', 'Pałac Schönbrunn, opera i wiedeńskie kawiarnie.', 'Schönbrunn Palace, the opera and Viennese coffee houses.'),
  ('at-salzburg', 'AT', 'Зальцбург', 'Salzburg', 'Salzburg', 'Salzburg', 47.81, 13.06, 'Батьківщина Моцарта з фортецею над старим містом.', 'Ojczyzna Mozarta z twierdzą nad starym miastem.', 'Mozart’s birthplace with a fortress above the old town.'),
  ('at-hallstatt', 'AT', 'Гальштат', 'Hallstatt', 'Hallstatt', 'Hallstatt', 47.56, 13.65, 'Казкове селище на березі альпійського озера.', 'Bajkowe miasteczko nad alpejskim jeziorem.', 'A fairy-tale village on the shore of an alpine lake.'),
  ('at-innsbruck', 'AT', 'Інсбрук', 'Innsbruck', 'Innsbruck', 'Innsbruck', 47.27, 11.4, 'Столиця Тиролю з підйомником просто з центру міста.', 'Stolica Tyrolu z kolejką prosto z centrum miasta.', 'Tyrol’s capital with a cable car straight from the city centre.'),
  ('ba-sarajevo', 'BA', 'Сараєво', 'Sarajewo', 'Sarajevo', 'Sarajevo', 43.86, 18.41, 'Базар Башчаршія та олімпійські гори.', 'Bazar Baščaršija i olimpijskie góry.', 'The Baščaršija bazaar and the Olympic mountains.'),
  ('ba-mostar', 'BA', 'Мостар', 'Mostar', 'Mostar', 'Mostar', 43.34, 17.81, 'Старий міст і стрибуни у річку Неретва.', 'Stary Most i skoczkowie do Neretwy.', 'The Old Bridge and divers leaping into the Neretva.'),
  ('ba-kravice', 'BA', 'Кравиця', 'Kravica', 'Kravica', 'Kravica waterfall', 43.16, 17.61, 'Водоспади, де можна купатися.', 'Wodospady, w których można się kąpać.', 'Waterfalls you can swim in.'),
  ('ba-jajce', 'BA', 'Яйце', 'Jajce', 'Jajce', 'Jajce', 44.34, 17.27, 'Водоспад просто в центрі міста.', 'Wodospad w samym centrum miasta.', 'A waterfall right in the middle of town.'),
  ('be-brussels', 'BE', 'Брюссель', 'Bruksela', 'Brussels', 'Brussels', 50.85, 4.35, 'Гран-Плас, Атоміум і штаб-квартира ЄС.', 'Grand-Place, Atomium i siedziba UE.', 'The Grand-Place, the Atomium and the EU headquarters.'),
  ('be-bruges', 'BE', 'Брюгге', 'Brugia', 'Bruges', 'Bruges', 51.21, 3.22, 'Канали та готичні будинки — «Північна Венеція».', 'Kanały i gotyckie kamienice — „Wenecja Północy”.', 'Canals and Gothic houses — the “Venice of the North”.'),
  ('be-ghent', 'BE', 'Гент', 'Gandawa', 'Ghent', 'Ghent', 51.05, 3.72, 'Замок графів Фландрії та студентська атмосфера.', 'Zamek Hrabiów Flandrii i studencki klimat.', 'The Castle of the Counts and a student vibe.'),
  ('be-antwerp', 'BE', 'Антверпен', 'Antwerpia', 'Antwerp', 'Antwerp', 51.22, 4.4, 'Діаманти, мода й будинок Рубенса.', 'Diamenty, moda i dom Rubensa.', 'Diamonds, fashion and the house of Rubens.'),
  ('bg-sofia', 'BG', 'Софія', 'Sofia', 'Sofia', 'Sofia', 42.7, 23.32, 'Собор Олександра Невського й гора Вітоша поруч.', 'Sobór Aleksandra Newskiego i góra Witosza obok.', 'Alexander Nevsky Cathedral with Mount Vitosha next door.'),
  ('bg-sozopol', 'BG', 'Созополь', 'Sozopol', 'Sozopol', 'Sozopol', 42.42, 27.7, 'Старе місто на мисі та піщані пляжі.', 'Stare miasto na cyplu i piaszczyste plaże.', 'An old town on a cape and sandy beaches.'),
  ('bg-plovdiv', 'BG', 'Пловдив', 'Płowdiw', 'Plovdiv', 'Plovdiv', 42.14, 24.75, 'Одне з найстаріших міст Європи з римським театром.', 'Jedno z najstarszych miast Europy z rzymskim teatrem.', 'One of Europe’s oldest cities, with a Roman theatre.'),
  ('bg-bansko', 'BG', 'Банско', 'Bansko', 'Bansko', 'Bansko', 41.84, 23.49, 'Лижі взимку й хайкінг у горах Пірин улітку.', 'Narty zimą i trekking w Pirynie latem.', 'Skiing in winter and hiking in the Pirin in summer.'),
  ('ch-zurich', 'CH', 'Цюрих', 'Zurych', 'Zürich', 'Zürich', 47.37, 8.54, 'Озеро, старе місто й найкращі шоколадниці.', 'Jezioro, stare miasto i najlepsze czekoladziarnie.', 'The lake, the old town and the best chocolatiers.'),
  ('ch-lucerne', 'CH', 'Люцерн', 'Lucerna', 'Lucerne', 'Lucerne', 47.05, 8.31, 'Дерев''яний міст Капельбрюкке та гора Пілатус.', 'Drewniany most Kapellbrücke i góra Pilatus.', 'The wooden Chapel Bridge and Mount Pilatus.'),
  ('ch-zermatt', 'CH', 'Церматт', 'Zermatt', 'Zermatt', 'Zermatt', 46.02, 7.75, 'Курорт без машин біля підніжжя Маттерхорну.', 'Kurort bez samochodów u stóp Matterhornu.', 'A car-free resort at the foot of the Matterhorn.'),
  ('ch-interlaken', 'CH', 'Інтерлакен', 'Interlaken', 'Interlaken', 'Interlaken', 46.69, 7.86, 'Між двома озерами, поруч Юнгфрау.', 'Między dwoma jeziorami, w pobliżu Jungfrau.', 'Between two lakes, near the Jungfrau.'),
  ('cy-limassol', 'CY', 'Лімасол', 'Limassol', 'Limassol', 'Limassol', 34.68, 33.04, 'Набережна, марина та винні села поряд.', 'Promenada, marina i winne wioski w pobliżu.', 'A promenade, a marina and wine villages nearby.'),
  ('cy-paphos', 'CY', 'Пафос', 'Pafos', 'Paphos', 'Paphos', 34.77, 32.42, 'Мозаїки, Гробниці царів і скеля Афродіти.', 'Mozaiki, Groby Królewskie i Skała Afrodyty.', 'Mosaics, the Tombs of the Kings and Aphrodite’s Rock.'),
  ('cy-ayia-napa', 'CY', 'Айя-Напа', 'Ayia Napa', 'Ayia Napa', 'Ayia Napa', 34.98, 34, 'Білі пляжі та нічні вечірки.', 'Białe plaże i nocne imprezy.', 'White beaches and night parties.'),
  ('cy-troodos', 'CY', 'Гори Троодос', 'Góry Troodos', 'Troodos Mountains', 'Troodos Mountains', 34.92, 32.86, 'Розписні церкви та прохолода в горах.', 'Malowane cerkwie i chłód gór.', 'Painted churches and cool mountain air.'),
  ('cz-prague', 'CZ', 'Прага', 'Praga', 'Prague', 'Prague', 50.08, 14.42, 'Карлів міст, астрономічний годинник і Празький град.', 'Most Karola, zegar astronomiczny i Hradczany.', 'Charles Bridge, the astronomical clock and Prague Castle.'),
  ('cz-cesky-krumlov', 'CZ', 'Чеський Крумлов', 'Czeski Krumlow', 'Český Krumlov', 'Český Krumlov', 48.81, 14.32, 'Казкове містечко в закруті Влтави.', 'Bajkowe miasteczko w zakolu Wełtawy.', 'A fairy-tale town in a bend of the Vltava.'),
  ('cz-karlovy-vary', 'CZ', 'Карлові Вари', 'Karlowe Wary', 'Karlovy Vary', 'Karlovy Vary', 50.23, 12.87, 'Мінеральні джерела та колонади курорту.', 'Źródła mineralne i kolumnady uzdrowiska.', 'Mineral springs and spa colonnades.'),
  ('cz-brno', 'CZ', 'Брно', 'Brno', 'Brno', 'Brno', 49.2, 16.61, 'Студентське місто з вілою Тугендгат.', 'Studenckie miasto z willą Tugendhatów.', 'A student city with the Villa Tugendhat.'),
  ('de-berlin', 'DE', 'Берлін', 'Berlin', 'Berlin', 'Berlin', 52.52, 13.4, 'Берлінська стіна, острів музеїв і найкращі клуби Європи.', 'Mur Berliński, Wyspa Muzeów i najlepsze kluby Europy.', 'The Berlin Wall, Museum Island and Europe’s best clubs.'),
  ('de-munich', 'DE', 'Мюнхен', 'Monachium', 'Munich', 'Munich', 48.14, 11.58, 'Октоберфест, Марієнплац і Альпи за годину їзди.', 'Oktoberfest, Marienplatz i Alpy godzinę drogi stąd.', 'Oktoberfest, Marienplatz and the Alps an hour away.'),
  ('de-hamburg', 'DE', 'Гамбург', 'Hamburg', 'Hamburg', 'Hamburg', 53.55, 9.99, 'Порт, канали Шпайхерштадту й філармонія Ельби.', 'Port, kanały Speicherstadt i Filharmonia nad Łabą.', 'The port, the canals of the Speicherstadt and the Elbphilharmonie.'),
  ('de-neuschwanstein', 'DE', 'Фюссен і Нойшванштайн', 'Füssen i Neuschwanstein', 'Füssen & Neuschwanstein', 'Neuschwanstein Castle', 47.56, 10.75, 'Замок, що надихнув Діснея, серед баварських гір.', 'Zamek, który zainspirował Disneya, wśród bawarskich gór.', 'The castle that inspired Disney, among Bavarian peaks.'),
  ('dk-copenhagen', 'DK', 'Копенгаген', 'Kopenhaga', 'Copenhagen', 'Copenhagen', 55.68, 12.57, 'Нюгавн, Тіволі й Русалонька.', 'Nyhavn, Tivoli i Mała Syrenka.', 'Nyhavn, Tivoli and the Little Mermaid.'),
  ('dk-billund', 'DK', 'Біллунн', 'Billund', 'Billund', 'Legoland Billund', 55.73, 9.13, 'Леголенд і LEGO House для всієї родини.', 'Legoland i LEGO House dla całej rodziny.', 'Legoland and LEGO House for the whole family.'),
  ('dk-aarhus', 'DK', 'Орхус', 'Aarhus', 'Aarhus', 'Aarhus', 56.16, 10.2, 'Райдужна панорама музею ARoS.', 'Tęczowa panorama muzeum ARoS.', 'The rainbow panorama of the ARoS museum.'),
