insert into public.facts (country_iso2, text_uk, text_pl, text_en) values
  ('AD', 'Андорра має двох співправителів — президента Франції та єпископа.', 'Andora ma dwóch współksiążąt — prezydenta Francji i biskupa.', 'Andorra has two co-princes: the President of France and a bishop.'),
  ('AD', 'Офіційна мова тут каталонська.', 'Językiem urzędowym jest kataloński.', 'Its official language is Catalan.'),
  ('AD', 'Країна не має аеропорту та залізниці.', 'Kraj nie ma lotniska ani kolei.', 'The country has no airport and no railway.'),
  ('AL', 'В Албанії побудували понад 170 тисяч бункерів за часів Енвера Ходжі.', 'Za czasów Envera Hodży w Albanii zbudowano ponad 170 tysięcy bunkrów.', 'Over 170,000 bunkers were built in Albania under Enver Hoxha.'),
  ('AL', 'Кивок головою тут часто означає «ні», а похитування — «так».', 'Kiwanie głową często oznacza tu „nie”, a kręcenie — „tak”.', 'A nod here often means “no” and a head shake means “yes”.'),
  ('AL', 'Мати Тереза мала албанське походження; її ім''ям названо аеропорт Тирани.', 'Matka Teresa była Albanką; jej imię nosi lotnisko w Tiranie.', 'Mother Teresa was of Albanian descent; Tirana airport bears her name.'),
  ('AT', 'Віденський зоопарк, заснований 1752 року, — найстаріший у світі.', 'Wiedeńskie zoo, założone w 1752 roku, jest najstarsze na świecie.', 'Vienna Zoo, founded in 1752, is the oldest in the world.'),
  ('AT', 'Понад 60% території Австрії займають Альпи.', 'Ponad 60% powierzchni Austrii zajmują Alpy.', 'The Alps cover more than 60% of Austria.'),
  ('AT', 'Відень регулярно визнають містом з найвищою якістю життя.', 'Wiedeń regularnie uznaje się za miasto o najwyższej jakości życia.', 'Vienna is regularly ranked the city with the best quality of life.'),
  ('BA', 'Сараєво приймало зимові Олімпійські ігри 1984 року.', 'Sarajewo gościło zimowe igrzyska olimpijskie w 1984 roku.', 'Sarajevo hosted the 1984 Winter Olympics.'),
  ('BA', 'Країна має лише 20 км морського узбережжя.', 'Kraj ma tylko 20 km wybrzeża morskiego.', 'The country has only 20 km of coastline.'),
  ('BA', 'Стрибки з мосту в Мостарі — традиція понад 400 років.', 'Skoki z mostu w Mostarze to tradycja licząca ponad 400 lat.', 'Diving from Mostar’s bridge is a tradition over 400 years old.'),
  ('BE', 'Картоплю фрі, ймовірно, вигадали саме в Бельгії.', 'Frytki najprawdopodobniej wymyślono w Belgii.', 'Fries were most likely invented in Belgium.'),
  ('BE', 'Тут варять понад 1500 сортів пива.', 'Warzy się tu ponad 1500 gatunków piwa.', 'Over 1,500 kinds of beer are brewed here.'),
  ('BE', 'Тінтін і смурфики — бельгійські комікси.', 'Tintin i Smerfy to belgijskie komiksy.', 'Tintin and the Smurfs are Belgian comics.'),
  ('BG', 'Болгари кивають головою на «ні» і хитають на «так».', 'Bułgarzy kiwają głową na „nie” i kręcą na „tak”.', 'Bulgarians nod for “no” and shake their heads for “yes”.'),
  ('BG', 'Кирилицю поширили саме з болгарських земель.', 'Cyrylica rozpowszechniła się właśnie z ziem bułgarskich.', 'The Cyrillic script spread from Bulgarian lands.'),
  ('BG', 'Болгарія — один з найбільших виробників трояндової олії.', 'Bułgaria jest jednym z największych producentów olejku różanego.', 'Bulgaria is one of the largest producers of rose oil.'),
  ('CH', 'У Швейцарії понад 1500 озер.', 'W Szwajcarii jest ponad 1500 jezior.', 'Switzerland has more than 1,500 lakes.'),
  ('CH', 'Країна має чотири офіційні мови.', 'Kraj ma cztery języki urzędowe.', 'The country has four official languages.'),
  ('CH', 'Швейцарці з''їдають близько 10 кг шоколаду на рік на людину.', 'Szwajcarzy zjadają około 10 kg czekolady rocznie na osobę.', 'The Swiss eat around 10 kg of chocolate per person a year.'),
  ('CY', 'За легендою, Афродіта вийшла з моря біля Пафоса.', 'Według legendy Afrodyta wyłoniła się z morza koło Pafos.', 'Legend says Aphrodite rose from the sea near Paphos.'),
  ('CY', 'На Кіпрі лівосторонній рух.', 'Na Cyprze obowiązuje ruch lewostronny.', 'Cyprus drives on the left.'),
  ('CY', 'Вино Коммандарія — одне з найстаріших у світі.', 'Wino Commandaria jest jednym z najstarszych na świecie.', 'Commandaria is one of the oldest named wines in the world.'),
  ('CZ', 'Чехи п''ють найбільше пива на людину у світі.', 'Czesi piją najwięcej piwa na osobę na świecie.', 'Czechs drink the most beer per person in the world.'),
  ('CZ', 'У Чехії понад 2000 замків.', 'W Czechach jest ponad 2000 zamków.', 'Czechia has over 2,000 castles.'),
  ('CZ', 'Слово «робот» вигадав чеський письменник Карел Чапек.', 'Słowo „robot” wymyślił czeski pisarz Karel Čapek.', 'The word “robot” was coined by Czech writer Karel Čapek.'),
  ('DE', 'У Німеччині понад 20 тисяч замків.', 'W Niemczech jest ponad 20 tysięcy zamków.', 'Germany has more than 20,000 castles.'),
  ('DE', 'На багатьох ділянках автобанів немає обмеження швидкості.', 'Na wielu odcinkach autostrad nie ma ograniczenia prędkości.', 'Many stretches of the Autobahn have no speed limit.'),
  ('DE', 'Тут випікають понад 3000 видів хліба.', 'Wypieka się tu ponad 3000 rodzajów chleba.', 'Over 3,000 kinds of bread are baked here.'),
