insert into public.reviews (user_id, author, lang, country_iso2, target_type, target_id, rating, text, created_at) values
  (null, 'Bartek S.', 'pl', 'AD', 'country', null, 5, 'Andora to był strzał w dziesiątkę. Piękne widoki, życzliwi ludzie, a escudella — palce lizać!', '2026-01-11T00:00:00.000Z'),
  (null, 'Emily R.', 'en', 'AD', 'city', 'ad-andorra', 5, 'Andorra la Vella is charming — we walked everywhere and found a great café on every corner.', '2026-09-19T00:00:00.000Z'),
  (null, 'Юлія С.', 'uk', 'AD', 'city', 'ad-soldeu', 5, 'Сольдеу дуже атмосферне, особливо зранку, поки немає туристів. Рекомендую піднятися на оглядовий майданчик.', '2026-09-25T00:00:00.000Z'),
  (null, 'James T.', 'en', 'AD', 'hotel', 'ad-h3', 5, 'Hotel Babot Ordino was spotless and the staff went out of their way to help us. Great location too.', '2026-08-21T00:00:00.000Z'),
  (null, 'Marek N.', 'pl', 'AD', 'hotel', 'ad-h4', 5, 'Hotel Casa Canut: czysto, wygodnie i blisko centrum. Obsługa bardzo pomocna.', '2026-05-30T00:00:00.000Z'),
  (null, 'Софія Д.', 'uk', 'AD', 'car', 'ad-c1', 5, 'Брали Seat Ibiza на тиждень — машина нова, видали швидко, без прихованих платежів. Об''їхали все узбережжя.', '2026-07-20T00:00:00.000Z'),
  (null, 'Daniel W.', 'en', 'AD', 'tour', 'ad-mountains', 5, 'We booked "Mountains and fresh air" and it was effortless — the route and the hotel were spot on.', '2026-10-24T00:00:00.000Z'),
  (null, 'Олена К.', 'uk', 'AL', 'country', null, 5, 'Албанія перевершила всі очікування. Люди привітні, все легко знайти, а тава-коси я досі згадую. Повернемося обов''язково!', '2026-07-28T00:00:00.000Z'),
  (null, 'Bartek S.', 'pl', 'AL', 'city', 'al-tirana', 5, 'Tirana zachwyca o każdej porze dnia. Najlepiej zwiedzać pieszo, bez pośpiechu.', '2026-08-21T00:00:00.000Z'),
  (null, 'Emily R.', 'en', 'AL', 'city', 'al-ksamil', 5, 'Ksamil is charming — we walked everywhere and found a great café on every corner.', '2026-07-08T00:00:00.000Z'),
  (null, 'Андрій М.', 'uk', 'AL', 'hotel', 'al-h3', 4, 'Ionian Blue Resort — саме те, що треба після довгого дня. Зручне ліжко й чудове розташування.', '2026-01-26T00:00:00.000Z'),
  (null, 'Ірина та Сергій', 'uk', 'AL', 'hotel', 'al-h4', 5, 'Зупинялися в Ksamil Lagoon Suites. Чисто, тихо, персонал усміхнений, сніданок смачний. Співвідношення ціна/якість — відмінне.', '2026-04-04T00:00:00.000Z'),
  (null, 'Марта Л.', 'uk', 'AL', 'car', 'al-c1', 5, 'Fiat Panda економна й зручна, на трасі тримає дорогу чудово. Оформлення через ETravel зайняло 5 хвилин.', '2026-02-27T00:00:00.000Z'),
  (null, 'Kasia Z.', 'pl', 'AL', 'tour', 'al-sea', 4, 'Wycieczka „Tydzień nad morzem” — świetnie zaplanowana trasa i hotel. Zero stresu, sam odpoczynek.', '2026-09-04T00:00:00.000Z'),
  (null, 'Катерина В.', 'uk', 'AT', 'country', null, 4, 'Їхали вперше й трохи хвилювалися, але путівник ETravel дуже допоміг. Австрія — ідеальна для тижня відпочинку.', '2026-08-04T00:00:00.000Z'),
  (null, 'Дмитро П.', 'uk', 'AT', 'city', 'at-vienna', 5, 'Провели в місті Відень три дні, і цього замало. Обов''язково беріть зручне взуття!', '2026-07-18T00:00:00.000Z'),
  (null, 'Magda i Tomek', 'pl', 'AT', 'city', 'at-salzburg', 5, 'Salzburg zachwyca o każdej porze dnia. Najlepiej zwiedzać pieszo, bez pośpiechu.', '2026-10-11T00:00:00.000Z'),
  (null, 'Марта Л.', 'uk', 'AT', 'hotel', 'at-h3', 4, 'Зупинялися в Tyrol Alpine Family Hotel. Чисто, тихо, персонал усміхнений, сніданок смачний. Співвідношення ціна/якість — відмінне.', '2026-10-10T00:00:00.000Z'),
  (null, 'Софія Д.', 'uk', 'AT', 'hotel', 'at-h4', 5, 'Зупинялися в Hallstatt Lakeside Boutique. Чисто, тихо, персонал усміхнений, сніданок смачний. Співвідношення ціна/якість — відмінне.', '2026-02-26T00:00:00.000Z'),
  (null, 'Ola M.', 'pl', 'AT', 'car', 'at-c1', 5, 'Wypożyczyliśmy Škoda Fabia — auto w świetnym stanie, odbiór bez kolejki. Polecam na zwiedzanie okolicy.', '2026-04-04T00:00:00.000Z'),
  (null, 'Максим Р.', 'uk', 'AT', 'tour', 'at-mountains', 5, '«Гори та свіже повітря» — найкращий подарунок собі за рік. Все за планом, а ціна така, як на сайті.', '2026-09-14T00:00:00.000Z'),
  (null, 'Марта Л.', 'uk', 'BA', 'country', null, 5, 'Чудова країна для подорожі з друзями. Ціни приємні, транспорт зручний. Єдине — влітку буває дуже людно.', '2026-04-05T00:00:00.000Z'),
  (null, 'Anna W.', 'pl', 'BA', 'city', 'ba-sarajevo', 5, 'Spędziliśmy w Sarajewo weekend — za mało! Świetne jedzenie i klimat.', '2026-03-27T00:00:00.000Z'),
  (null, 'Agnieszka P.', 'pl', 'BA', 'city', 'ba-mostar', 4, 'Mostar zachwyca o każdej porze dnia. Najlepiej zwiedzać pieszo, bez pośpiechu.', '2026-05-15T00:00:00.000Z'),
