  (null, 'Piotr K.', 'pl', 'XK', 'country', null, 5, 'Kosowo to był strzał w dziesiątkę. Piękne widoki, życzliwi ludzie, a flija — palce lizać!', '2026-05-06T00:00:00.000Z'),
  (null, 'Hannah K.', 'en', 'XK', 'city', 'xk-pristina', 4, 'Pristina is charming — we walked everywhere and found a great café on every corner.', '2026-01-27T00:00:00.000Z'),
  (null, 'Олександр Б.', 'uk', 'XK', 'city', 'xk-prizren', 5, 'Провели в місті Прізрен три дні, і цього замало. Обов''язково беріть зручне взуття!', '2026-02-10T00:00:00.000Z'),
  (null, 'Ірина та Сергій', 'uk', 'XK', 'hotel', 'xk-h3', 5, 'Зупинялися в Rugova Camp Hotel. Чисто, тихо, персонал усміхнений, сніданок смачний. Співвідношення ціна/якість — відмінне.', '2026-05-01T00:00:00.000Z'),
  (null, 'Тарас Г.', 'uk', 'XK', 'hotel', 'xk-h4', 4, 'Hotel Prizren Centre — саме те, що треба після довгого дня. Зручне ліжко й чудове розташування.', '2026-04-19T00:00:00.000Z'),
  (null, 'Максим Р.', 'uk', 'XK', 'car', 'xk-c1', 5, 'Брали VW Golf на тиждень — машина нова, видали швидко, без прихованих платежів. Об''їхали все узбережжя.', '2026-04-02T00:00:00.000Z'),
  (null, 'Софія Д.', 'uk', 'XK', 'tour', 'xk-mountains', 5, 'Брали тур «Гори та свіже повітря» і не пошкодували: маршрут продуманий, готель класний, нічого не треба було організовувати самим.', '2026-08-15T00:00:00.000Z'),
  (null, 'Олександр Б.', 'uk', null, 'service', null, 5, 'Найзручніший сервіс для планування, яким я користувалася. Глобус — це просто вау, а підбір під бюджет реально працює.', '2026-10-26T00:00:00.000Z'),
  (null, 'Андрій М.', 'uk', null, 'service', null, 5, 'Сподобалося, що одразу видно повну ціну: переліт, готель, машина. Ніяких сюрпризів.', '2026-10-09T00:00:00.000Z'),
  (null, 'Agnieszka P.', 'pl', null, 'service', null, 5, 'Bardzo wygodny serwis — dobór podróży pod budżet działa świetnie, a globus robi wrażenie.', '2026-09-22T00:00:00.000Z'),
  (null, 'Олена К.', 'uk', null, 'service', null, 4, 'Красивий і швидкий сайт. Хотілося б ще більше міст, але й так дуже круто.', '2026-09-05T00:00:00.000Z'),
  (null, 'Liam O.', 'en', null, 'service', null, 5, 'Beautiful site and genuinely useful trip planner. Booking took less than a minute.', '2026-08-19T00:00:00.000Z'),
  (null, 'Ola M.', 'pl', null, 'service', null, 5, 'Wszystko po polsku, jasne ceny i szybka rezerwacja. Polecam!', '2026-08-02T00:00:00.000Z'),
  (null, 'Катерина В.', 'uk', null, 'service', null, 5, 'Поповнила гаманець і оплатила тур за хвилину. Все зрозуміло навіть мамі 🙂', '2026-07-16T00:00:00.000Z');
